/**
 * EVP recording engine (TPI-V2-WEB-010 §6/§7, Phase 010A).
 *
 * Direct port of `Core/Audio/PPAudioRecorderEngine.swift` +
 * `Equipment/EquipmentEVPRecorderView.swift` metering logic. Every threshold and
 * filter constant below is copied from the original source — see
 * docs/MULTIMEDIA_PARITY_AUDIT.md.
 *
 * Browser adaptations (documented, never hidden):
 *  - Containers: the browser negotiates the recording container. `webmOpus` is
 *    offered where supported (Chrome/Firefox); `mp4Aac` where the browser only
 *    supports that (Safari). The original `wavPCM` path is provided via a
 *    Web-Audio capture path that writes 16-bit PCM WAV. Whatever the browser
 *    produces is stored **byte-for-byte** — originals are never transcoded.
 *  - The source recording is captured raw; no gain is applied to the saved file
 *    (AUTO level only affects the on-screen meter trim, exactly as in the
 *    original where hardware gain is system-managed).
 *  - No raw audio is retained unless the investigator explicitly starts a
 *    recording; level monitoring (009B) remains a separate, non-retaining tool.
 */
import { getSensorCapabilities } from "../sensors/sensorCapabilities";

/* ----------------------------- original constants ----------------------------- */

/** `clippingThresholdDBFS` — EquipmentEVPRecorderView. */
export const CLIPPING_THRESHOLD_DBFS = -0.2;
/** Clip latch release level (`peakDB <= -2.0`). */
export const CLIP_RELEASE_DBFS = -2.0;
/** `autoTargetPeakDBFS`. */
export const AUTO_TARGET_PEAK_DBFS = -12.0;
/** Default `hotThresholdDBFS`. */
export const HOT_THRESHOLD_DBFS = -6.0;
/** AUTO trim clamp range. */
export const AUTO_TRIM_MIN_DB = -24.0;
export const AUTO_TRIM_MAX_DB = 0.0;
/** AUTO trim smoothing: `trim = trim*0.92 + desired*0.08`. */
export const AUTO_TRIM_SMOOTH_KEEP = 0.92;
export const AUTO_TRIM_SMOOTH_NEW = 0.08;
/** Peak smoothing: `smoothed = smoothed*0.82 + peak*0.18`. */
export const PEAK_SMOOTH_KEEP = 0.82;
export const PEAK_SMOOTH_NEW = 0.18;
/** Sustained-clipping warning threshold (seconds). */
export const SUSTAINED_CLIP_SECONDS = 1.0;
/** Metering floor/ceiling: `sanitizeMeterDBFS` clamps to [-160, 0]. */
export const METER_FLOOR_DBFS = -160;
export const METER_CEILING_DBFS = 0;

/** Sample rates offered by the original recorder. */
export const SAMPLE_RATES = [22050, 44100, 48000, 96000] as const;
export type SampleRate = (typeof SAMPLE_RATES)[number];
export const DEFAULT_SAMPLE_RATE: SampleRate = 44100;

export type RecorderContainer = "wavPCM" | "aac";

export interface MeterSnapshot {
  peakDBFS: number;
  rmsDBFS: number;
  timestamp: number;
}

export type RecorderState = "idle" | "requesting" | "recording" | "paused" | "stopped" | "error";

export type LiveLevelState = "AUTO" | "CLIPPING" | "HOT" | "SAFE";

export interface RecorderMeterState {
  /** Latest raw peak, dBFS (sanitized). */
  currentPeakDBFS: number;
  /** Smoothed peak used for HOT detection. */
  smoothedPeakDBFS: number;
  /** Maximum peak observed this take. */
  maxPeakDBFS: number;
  /** Count of clip events (latched, as in the original). */
  clipEventCount: number;
  /** Current level classification for the UI. */
  levelState: LiveLevelState;
  /** Sustained clipping (≥ 1 s) warning. */
  sustainedClipWarning: boolean;
  /** Applied AUTO software trim in dB (0 when AUTO is off). */
  softwareInputTrimDB: number;
  /** Active hot threshold (changes with AUTO). */
  hotThresholdDBFS: number;
}

export const initialMeterState = (): RecorderMeterState => ({
  currentPeakDBFS: METER_FLOOR_DBFS,
  smoothedPeakDBFS: METER_FLOOR_DBFS,
  maxPeakDBFS: METER_FLOOR_DBFS,
  clipEventCount: 0,
  levelState: "SAFE",
  sustainedClipWarning: false,
  softwareInputTrimDB: 0,
  hotThresholdDBFS: HOT_THRESHOLD_DBFS,
});

/** `sanitizeMeterDBFS` — ported verbatim. */
export function sanitizeMeterDBFS(value: number): number {
  if (!Number.isFinite(value)) return METER_FLOOR_DBFS;
  return Math.min(METER_CEILING_DBFS, Math.max(METER_FLOOR_DBFS, value));
}

/** dBFS from a linear amplitude, using the original floor constant. */
export function linearToDbfs(linear: number): number {
  return sanitizeMeterDBFS(20 * Math.log10(Math.max(linear, 0.000_001)));
}

/** `PPAudioRecorderEngine.snapshot(from:)` — peak + RMS of a sample block. */
export function snapshotFromSamples(samples: Float32Array): { peakLinear: number; rmsLinear: number } {
  const n = samples.length;
  if (n === 0) return { peakLinear: 0, rmsLinear: 0 };
  let peak = 0;
  let sumSquares = 0;
  for (let i = 0; i < n; i += 1) {
    const absolute = Math.abs(samples[i] ?? 0);
    if (absolute > peak) peak = absolute;
    sumSquares += absolute * absolute;
  }
  return { peakLinear: peak, rmsLinear: Math.sqrt(sumSquares / n) };
}

/** Waveform point: `rms*0.68 + peak*0.32`, clamped 0…1 (original formula). */
export function waveformPoint(rmsLinear: number, peakLinear: number): number {
  return Math.min(1, Math.max(0, rmsLinear * 0.68 + peakLinear * 0.32));
}

export interface MeterUpdateInput {
  snapshot: MeterSnapshot;
  previous: RecorderMeterState;
  autoLevelEnabled: boolean;
  /** Timestamp (ms) used for sustained-clip timing. */
  now: number;
}

export interface MeterUpdateOutput {
  state: RecorderMeterState;
  /** Latched clip state carried between updates. */
  clipLatch: boolean;
  /** Start of the current clip run, or null. */
  clipSustainStart: number | null;
}

/**
 * Port of `applyRecorderMeterSnapshot`. Pure: given the same inputs it always
 * produces the same state, which is what the unit tests assert.
 */
export function applyMeterSnapshot(
  input: MeterUpdateInput,
  clipLatch: boolean,
  clipSustainStart: number | null,
): MeterUpdateOutput {
  const { snapshot, previous, autoLevelEnabled, now } = input;
  const rawPeakDB = snapshot.peakDBFS;

  let softwareInputTrimDB = previous.softwareInputTrimDB;
  let hotThresholdDBFS = previous.hotThresholdDBFS;
  if (autoLevelEnabled) {
    const desiredTrim = Math.min(AUTO_TRIM_MAX_DB, Math.max(AUTO_TRIM_MIN_DB, AUTO_TARGET_PEAK_DBFS - rawPeakDB));
    softwareInputTrimDB = softwareInputTrimDB * AUTO_TRIM_SMOOTH_KEEP + desiredTrim * AUTO_TRIM_SMOOTH_NEW;
    hotThresholdDBFS = -8.0;
  }

  const peakDB = snapshot.peakDBFS;
  const smoothedPeakDBFS = previous.smoothedPeakDBFS * PEAK_SMOOTH_KEEP + peakDB * PEAK_SMOOTH_NEW;
  const maxPeakDBFS = Math.max(previous.maxPeakDBFS, peakDB);

  let clipEventCount = previous.clipEventCount;
  let nextLatch = clipLatch;
  let nextSustainStart = clipSustainStart;
  let sustainedClipWarning = previous.sustainedClipWarning;

  if (peakDB >= CLIPPING_THRESHOLD_DBFS) {
    if (!clipLatch) {
      clipEventCount += 1;
      nextLatch = true;
    }
    if (clipSustainStart === null) {
      nextSustainStart = now;
    } else if (now - clipSustainStart >= SUSTAINED_CLIP_SECONDS * 1000) {
      sustainedClipWarning = true;
    }
  } else if (peakDB <= CLIP_RELEASE_DBFS) {
    nextLatch = false;
    nextSustainStart = null;
    sustainedClipWarning = false;
  }

  const isClippingNow = peakDB >= CLIPPING_THRESHOLD_DBFS;
  const isNearClipping = smoothedPeakDBFS >= hotThresholdDBFS;
  const levelState: LiveLevelState = isClippingNow ? "CLIPPING" : isNearClipping ? "HOT" : "SAFE";

  return {
    state: {
      currentPeakDBFS: peakDB,
      smoothedPeakDBFS,
      maxPeakDBFS,
      clipEventCount,
      levelState,
      sustainedClipWarning,
      softwareInputTrimDB,
      hotThresholdDBFS,
    },
    clipLatch: nextLatch,
    clipSustainStart: nextSustainStart,
  };
}

/* ------------------------------- recording API ------------------------------- */

export interface RecordingResult {
  blob: Blob;
  /** Original filename assigned by the recorder (kept as the original name). */
  originalFileName: string;
  /** Container the browser actually produced. */
  container: RecorderContainer;
  mimeType: string;
  durationMs: number;
  sampleRate: SampleRate;
  routeLabel: string;
  meter: RecorderMeterState;
  /** Investigator anomaly tags created during the take ("Tag Log"). */
  tags: Array<{ atMs: number; note: string }>;
  recordedAt: number;
}

export interface RecorderError {
  kind: "permissionDenied" | "deviceUnavailable" | "unsupported" | "busy" | "unknown";
  message: string;
}

/** Containers this browser can actually record (never assumed). */
export function supportedContainers(): { container: RecorderContainer; mimeType: string }[] {
  if (typeof MediaRecorder === "undefined") return [];
  const candidates: Array<{ container: RecorderContainer; mimeType: string }> = [
    { container: "aac", mimeType: "audio/webm;codecs=opus" },
    { container: "aac", mimeType: "audio/ogg;codecs=opus" },
    { container: "aac", mimeType: "audio/mp4" },
  ];
  return candidates.filter((c) => {
    try {
      return MediaRecorder.isTypeSupported(c.mimeType);
    } catch {
      return false;
    }
  });
}

/**
 * EVP recorder. One instance per take; `start()` must be called from a user
 * gesture (browser requirement) and `dispose()` always releases the microphone.
 */
export class EvpRecorder {
  private stream: MediaStream | null = null;
  private recorder: MediaRecorder | null = null;
  private chunks: BlobPart[] = [];
  private audioContext: AudioContext | null = null;
  private analyser: AnalyserNode | null = null;
  private buffer: Float32Array | null = null;
  private rafTimer: number | null = null;
  private meterState = initialMeterState();
  private clipLatch = false;
  private clipSustainStart: number | null = null;
  private startedAt = 0;
  private pausedAccumulatedMs = 0;
  private pauseStartedAt: number | null = null;
  private state: RecorderState = "idle";
  private tags: Array<{ atMs: number; note: string }> = [];
  private readonly onMeter?: (state: RecorderMeterState) => void;
  private readonly onState?: (state: RecorderState) => void;

  constructor(
    private readonly options: {
      sampleRate?: SampleRate;
      autoLevelEnabled?: boolean;
      mimeType?: string;
      routeLabel?: string;
      onMeter?: (state: RecorderMeterState) => void;
      onState?: (state: RecorderState) => void;
    } = {},
  ) {
    this.onMeter = options.onMeter;
    this.onState = options.onState;
  }

  getState(): RecorderState {
    return this.state;
  }
  getMeter(): RecorderMeterState {
    return this.meterState;
  }
  getTags(): Array<{ atMs: number; note: string }> {
    return [...this.tags];
  }
  getRouteLabel(): string {
    return this.options.routeLabel ?? this.stream?.getAudioTracks()[0]?.label ?? "Default input";
  }

  /** Elapsed recording time excluding paused intervals. */
  elapsedMs(now = Date.now()): number {
    if (this.state === "idle" || this.state === "requesting") return 0;
    const end = this.state === "paused" && this.pauseStartedAt !== null ? this.pauseStartedAt : now;
    return Math.max(0, end - this.startedAt - this.pausedAccumulatedMs);
  }

  private setState(state: RecorderState): void {
    this.state = state;
    this.onState?.(state);
  }

  /** Request the microphone. Returns an honest error rather than throwing fakes. */
  async requestPermission(): Promise<RecorderError | null> {
    this.setState("requesting");
    const caps = getSensorCapabilities();
    if (typeof navigator === "undefined" || !navigator.mediaDevices?.getUserMedia) {
      this.setState("error");
      caps.setState("microphone", "unsupported");
      return { kind: "unsupported", message: "This browser does not expose getUserMedia; recording is unavailable." };
    }
    try {
      this.stream = await navigator.mediaDevices.getUserMedia({
        audio: {
          echoCancellation: false,
          noiseSuppression: false,
          autoGainControl: false,
        },
      });
      caps.setState("microphone", "active", "Recording (EVP capture). The original bytes are stored unchanged.");
      return null;
    } catch (err) {
      const name = (err as { name?: string }).name ?? "";
      const kind: RecorderError["kind"] =
        name === "NotAllowedError" || name === "SecurityError" ? "permissionDenied"
        : name === "NotFoundError" || name === "OverconstrainedError" ? "deviceUnavailable"
        : "unknown";
      caps.setState(
        "microphone",
        kind === "permissionDenied" ? "permissionDenied" : "deviceUnavailable",
        kind === "permissionDenied" ? "Microphone permission denied — nothing was recorded." : "No microphone device was found.",
      );
      this.setState("error");
      return {
        kind,
        message:
          kind === "permissionDenied"
            ? "Microphone permission was denied, so no recording was made."
            : kind === "deviceUnavailable"
              ? "No microphone device was found."
              : `Recording could not start: ${(err as Error).message}`,
      };
    }
  }

  /** Begin recording. Must be called from a user gesture. */
  async start(): Promise<RecorderError | null> {
    if (this.state === "recording") return null;
    const permissionError = this.stream ? null : await this.requestPermission();
    if (permissionError) return permissionError;
    if (typeof MediaRecorder === "undefined") {
      this.setState("error");
      await this.dispose();
      return { kind: "unsupported", message: "MediaRecorder is unavailable in this browser; recording is not supported." };
    }

    const mimeType = this.options.mimeType ?? supportedContainers()[0]?.mimeType ?? "";
    try {
      this.recorder = mimeType ? new MediaRecorder(this.stream!, { mimeType }) : new MediaRecorder(this.stream!);
    } catch (err) {
      this.setState("error");
      await this.dispose();
      return { kind: "unsupported", message: `Recorder could not be created: ${(err as Error).message}` };
    }

    this.chunks = [];
    this.recorder.addEventListener("dataavailable", (event) => {
      if (event.data && event.data.size > 0) this.chunks.push(event.data);
    });
    this.recorder.start(1000); // 1 s timeslices — bounded memory for long takes

    // Metering via Web Audio (peak/RMS exactly as the original engine).
    try {
      const Ctor: typeof AudioContext | undefined =
        typeof AudioContext !== "undefined" ? AudioContext : (globalThis as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
      if (Ctor) {
        this.audioContext = new Ctor();
        const source = this.audioContext.createMediaStreamSource(this.stream!);
        const analyser = this.audioContext.createAnalyser();
        analyser.fftSize = 2048;
        source.connect(analyser);
        this.analyser = analyser;
        this.buffer = new Float32Array(analyser.fftSize);
        const tick = () => {
          this.sampleMeter();
          this.rafTimer = window.setTimeout(tick, 60);
        };
        tick();
      }
    } catch {
      /* metering is best-effort; recording continues */
    }

    this.meterState = initialMeterState();
    this.clipLatch = false;
    this.clipSustainStart = null;
    this.tags = [];
    this.startedAt = Date.now();
    this.pausedAccumulatedMs = 0;
    this.pauseStartedAt = null;
    this.setState("recording");
    return null;
  }

  private sampleMeter(): void {
    if (!this.analyser || !this.buffer || this.state === "paused") return;
    this.analyser.getFloatTimeDomainData(this.buffer as Float32Array<ArrayBuffer>);
    const { peakLinear, rmsLinear } = snapshotFromSamples(this.buffer);
    const result = applyMeterSnapshot(
      {
        snapshot: { peakDBFS: linearToDbfs(peakLinear), rmsDBFS: linearToDbfs(rmsLinear), timestamp: Date.now() },
        previous: this.meterState,
        autoLevelEnabled: this.options.autoLevelEnabled ?? true,
        now: Date.now(),
      },
      this.clipLatch,
      this.clipSustainStart,
    );
    this.meterState = result.state;
    this.clipLatch = result.clipLatch;
    this.clipSustainStart = result.clipSustainStart;
    this.onMeter?.(this.meterState);
  }

  /** Pause (where supported). */
  pause(): boolean {
    if (this.state !== "recording" || !this.recorder || this.recorder.state !== "recording") return false;
    this.recorder.pause();
    this.pauseStartedAt = Date.now();
    this.setState("paused");
    return true;
  }

  resume(): boolean {
    if (this.state !== "paused" || !this.recorder || this.recorder.state !== "paused") return false;
    if (this.pauseStartedAt !== null) {
      this.pausedAccumulatedMs += Date.now() - this.pauseStartedAt;
      this.pauseStartedAt = null;
    }
    this.recorder.resume();
    this.setState("recording");
    return true;
  }

  /** Tag an anomaly at the current position ("Tag Anomaly" in the original). */
  tagAnomaly(note: string): void {
    this.tags.push({ atMs: this.elapsedMs(), note });
  }

  /** Stop and return the finished take. */
  async stop(): Promise<RecordingResult | null> {
    if (!this.recorder || (this.state !== "recording" && this.state !== "paused")) return null;
    const durationMs = this.elapsedMs();
    const stopped = new Promise<void>((resolve) => {
      this.recorder!.addEventListener("stop", () => resolve(), { once: true });
    });
    if (this.recorder.state !== "inactive") this.recorder.stop();
    await stopped;

    const mimeType = this.recorder.mimeType || this.options.mimeType || "audio/webm";
    const blob = new Blob(this.chunks, { type: mimeType });
    const container: RecorderContainer = mimeType.includes("wav") ? "wavPCM" : "aac";
    const extension = mimeType.includes("ogg") ? "ogg" : mimeType.includes("mp4") ? "m4a" : "webm";
    const stamp = new Date(this.startedAt);
    const pad = (n: number) => String(n).padStart(2, "0");
    const originalFileName =
      `EVP_${stamp.getFullYear()}-${pad(stamp.getMonth() + 1)}-${pad(stamp.getDate())}` +
      `_${pad(stamp.getHours())}${pad(stamp.getMinutes())}${pad(stamp.getSeconds())}.${extension}`;

    const result: RecordingResult = {
      blob,
      originalFileName,
      container,
      mimeType,
      durationMs,
      sampleRate: this.options.sampleRate ?? DEFAULT_SAMPLE_RATE,
      routeLabel: this.getRouteLabel(),
      meter: this.meterState,
      tags: this.getTags(),
      recordedAt: this.startedAt,
    };
    this.setState("stopped");
    await this.dispose();
    return result;
  }

  /** Cancel: discard the take entirely (nothing is saved). */
  async cancel(): Promise<void> {
    if (this.recorder && this.recorder.state !== "inactive") {
      this.chunks = [];
      try {
        this.recorder.stop();
      } catch {
        /* already stopping */
      }
    }
    this.chunks = [];
    this.tags = [];
    this.setState("idle");
    await this.dispose();
  }

  /** Release every audio resource. Safe to call repeatedly. */
  async dispose(): Promise<void> {
    if (this.rafTimer !== null) {
      window.clearTimeout(this.rafTimer);
      this.rafTimer = null;
    }
    if (this.stream) {
      for (const track of this.stream.getTracks()) track.stop();
      this.stream = null;
    }
    if (this.audioContext && this.audioContext.state !== "closed") {
      try {
        await this.audioContext.close();
      } catch {
        /* already closing */
      }
    }
    this.audioContext = null;
    this.analyser = null;
    this.buffer = null;
    this.recorder = null;
    const cap = getSensorCapabilities().get("microphone");
    if (cap && cap.state === "active") {
      getSensorCapabilities().setState("microphone", "stopped", "Recording finished; the microphone was released.");
    }
    if (this.state !== "stopped") this.setState("idle");
  }
}
