/**
 * EVP Recorder view (TPI-V2-WEB-010 §6/§21, Phase 010A).
 *
 * Interface and terminology ported from `Equipment/EquipmentEVPRecorderView.swift`:
 * "Electronic Voice Phenomena Capture", "Case + Room Context", "Input Level"
 * (AUTO/CLIPPING/HOT/SAFE, Peak/Max dBFS, Clip Events), "Recording Controls"
 * (sample rate), "Route: <input>", "Tag Log", "Recorder References (This Case)",
 * "Open in Audio Analysis".
 *
 * Storage goes through the existing evidence pipeline (OPFS + SHA-256); the
 * recording is saved to the case as an ORIGINAL audio item and appears in the
 * Evidence Library and Timeline. Nothing is transcoded or uploaded.
 */
import "../dashboard/dashboard.css";
import { getDb } from "../../core/db";
import { CaseRepository } from "../../core/repositories/caseRepository";
import { EvidenceRepository } from "../../core/repositories/evidenceRepository";
import { AuditService } from "../../core/audit";
import { getSensorCapabilities } from "../../core/sensors/sensorCapabilities";
import {
  DEFAULT_SAMPLE_RATE,
  EvpRecorder,
  SAMPLE_RATES,
  supportedContainers,
  type MeterSnapshot,
  type RecorderMeterState,
  type RecordingResult,
  type SampleRate,
} from "../../core/media/audioRecorder";
import type { CaseRecord } from "../../core/types";
import { esc, viewShell, wireBackButton } from "../dashboard/shell";
import { mountView, onDelegate, invalidateView } from "../../shared/uidom";
import { navigate } from "../../app/router";

const db = () => getDb();

interface EvpUiState {
  caseId: string | null;
  sessionId: string;
  sampleRate: SampleRate;
  autoLevel: boolean;
  roomId: string;
  tags: Array<{ atMs: number; note: string }>;
  lastResult: RecordingResult | null;
  lastError: string;
  status: string;
}

const ui = new WeakMap<HTMLElement, EvpUiState>();
let activeRecorder: EvpRecorder | null = null;

function st(container: HTMLElement): EvpUiState {
  let s = ui.get(container);
  if (!s) {
    s = {
      caseId: null,
      sessionId: "",
      sampleRate: DEFAULT_SAMPLE_RATE,
      autoLevel: true,
      roomId: "",
      tags: [],
      lastResult: null,
      lastError: "",
      status: "Ready.",
    };
    ui.set(container, s);
  }
  return s;
}

function fmtDuration(ms: number): string {
  const total = Math.max(0, Math.floor(ms / 1000));
  return `${String(Math.floor(total / 60)).padStart(2, "0")}:${String(total % 60).padStart(2, "0")}`;
}

const LEVEL_CLASS: Record<string, string> = {
  CLIPPING: "error",
  HOT: "pending",
  SAFE: "implemented",
  AUTO: "",
};

export async function renderEvpRecorder(container: HTMLElement, caseId?: string): Promise<void> {
  const s = st(container);
  if (caseId) s.caseId = caseId;
  const cases = await new CaseRepository(db()).listCases(200);
  if (!s.caseId && cases.length > 0) s.caseId = cases[0]!.id;
  const caseRecord = s.caseId ? cases.find((c) => c.id === s.caseId) : undefined;

  const structure = caseRecord ? await db().propertyStructures.where("caseId").equals(caseRecord.id).first() : undefined;
  const rooms = structure
    ? (await db().structureRooms.where("structureId").equals(structure.id).toArray()).filter((r) => !r.archived)
    : [];
  const sessions = caseRecord
    ? (await db().sessions.where("caseId").equals(caseRecord.id).toArray()).sort((a, b) => b.startedAt - a.startedAt)
    : [];
  if (!s.sessionId || !sessions.some((session) => session.id === s.sessionId)) {
    s.sessionId = sessions.find((session) => session.status === "active" || session.status === "paused")?.id ?? "";
  }
  const recorderRefs = caseRecord
    ? (await db().evidence.where("caseId").equals(caseRecord.id).toArray())
        .filter((e) => e.mediaType === "audio" && e.kind === "original")
        .sort((a, b) => b.createdAt - a.createdAt)
        .slice(0, 25)
    : [];
  const capability = getSensorCapabilities().get("microphone");
  const containers = supportedContainers();

  invalidateView(container);
  mountView(
    container,
    viewShell(
      "Electronic Voice Phenomena Capture",
      `
      <div class="case-form" data-root="evp-recorder" data-epoch="${Date.now()}-${Math.random()}">
        <p class="primary-line">Record with built-in or external microphone. Save directly to case audio readings.</p>
        <p class="cc-meta">Microphone: <strong>${esc(capability?.state ?? "unknown")}</strong> — ${esc(capability?.detail ?? "")}</p>
        ${
          containers.length === 0
            ? `<p class="cc-count" role="alert"><strong>This browser cannot record audio</strong> (MediaRecorder unavailable). The recorder is shown so the original interface is preserved, but no recording can be saved.</p>`
            : ""
        }

        <h3 class="cc-section-title">Case + Room Context</h3>
        <div class="detail-grid">
          <div class="detail-field"><label for="evp-case">Active case</label>
            <select id="evp-case">
              ${cases.length === 0 ? '<option value="">— no cases yet —</option>' : cases.map((c: CaseRecord) => `<option value="${c.id}"${c.id === s.caseId ? " selected" : ""}>${esc(c.caseNumber)} — ${esc(c.title)}</option>`).join("")}
            </select></div>
          <div class="detail-field"><label for="evp-room">Room</label>
            <select id="evp-room">
              <option value="">Unassigned</option>
              ${rooms.map((r) => `<option value="${r.id}"${s.roomId === r.id ? " selected" : ""}>${esc(r.name)}</option>`).join("")}
            </select></div>
          <div class="detail-field"><label for="evp-session">Investigation session</label>
            <select id="evp-session">
              <option value="">— no session association —</option>
              ${sessions.map((session) => `<option value="${session.id}"${session.id === s.sessionId ? " selected" : ""}>${esc(session.status)} — ${new Date(session.startedAt).toLocaleString()}</option>`).join("")}
            </select></div>
        </div>
        <p class="cc-meta">Case, room and session are stored on the original audio evidence. A session is optional but is never inferred from the filename or current page.</p>

        <h3 class="cc-section-title">Recording Controls</h3>
        <div class="detail-grid">
          <div class="detail-field"><label for="evp-rate">Sample rate</label>
            <select id="evp-rate">
              ${SAMPLE_RATES.map((r) => `<option value="${r}"${r === s.sampleRate ? " selected" : ""}>${Math.round(r / 1000)} kHz</option>`).join("")}
            </select></div>
          <div class="detail-field"><label for="evp-auto">AUTO Level</label>
            <label class="cc-count"><input type="checkbox" id="evp-auto" ${s.autoLevel ? "checked" : ""}> Manage capture headroom and warning threshold automatically</label></div>
        </div>
        <div class="form-actions">
          <button class="button-primary" id="evp-record" type="button">Start Recording</button>
          <button class="button-secondary" id="evp-pause" type="button" hidden>Pause</button>
          <button class="button-secondary" id="evp-stop" type="button" hidden>Stop &amp; Save</button>
          <button class="back-button" id="evp-cancel" type="button" hidden>Cancel Recording…</button>
        </div>

        <h3 class="cc-section-title">Input Level</h3>
        <div class="case-form" id="evp-level">
          <p class="cc-count">
            State: <span class="status-badge ${LEVEL_CLASS["AUTO"]}" id="evp-level-state">AUTO</span>
            <strong id="evp-peak">Peak: -160.0 dBFS</strong> • <span id="evp-max">Max: -160.0 dBFS</span>
            • <span id="evp-clips">Clip Events: 0</span>
            • <span id="evp-timer">00:00</span>
          </p>
          <div class="meter" role="meter" aria-valuenow="0" aria-valuemin="-60" aria-valuemax="0" aria-label="Input level in dBFS">
            <div class="fill" id="evp-meter-fill" style="width:0%"></div>
          </div>
          <p class="cc-meta" id="evp-route">Route: ${esc(activeRecorder?.getRouteLabel() ?? "Default input")}</p>
          <p class="cc-meta" id="evp-warning"></p>
        </div>

        <h3 class="cc-section-title">Recording Consent</h3>
        <p class="cc-meta"><strong>Application microphone permission is not recording consent.</strong> Before recording anyone,
        confirm the applicable consent documents are completed for this case (the Audio, Video, and Photography Investigation
        Consent in the Documents Center covers recording scope for the property). Recording another person without their consent
        may be unlawful in your jurisdiction.</p>

        <h3 class="cc-section-title">Tag Log</h3>
        <div class="form-actions">
          <button class="button-secondary" id="evp-tag" type="button" disabled>Tag Anomaly</button>
        </div>
        <div id="evp-tags">${s.tags.length === 0 ? '<div class="cc-empty">No anomaly tags yet. Tap Tag Anomaly during recording/playback.</div>' : s.tags.map((t) => `<div class="case-row"><div><div class="case-title">${fmtDuration(t.atMs)}</div><div class="case-meta">${esc(t.note)}</div></div></div>`).join("")}</div>

        <h3 class="cc-section-title">Last Take</h3>
        <div id="evp-result">
          ${
            s.lastResult
              ? `<div class="case-row"><div>
                   <div class="case-title">${esc(s.lastResult.originalFileName)}</div>
                   <div class="case-meta">${fmtDuration(s.lastResult.durationMs)} • ${esc(s.lastResult.mimeType)} • ${Math.round(s.lastResult.blob.size / 1024)} KB • ${esc(s.lastResult.routeLabel)} • max ${s.lastResult.meter.maxPeakDBFS.toFixed(1)} dBFS • ${s.lastResult.meter.clipEventCount} clip event(s)</div>
                 </div></div>
                 <audio controls src="${URL.createObjectURL(s.lastResult.blob)}" style="width:100%" aria-label="Last recording playback"></audio>`
              : '<div class="cc-empty">No recording in this session yet.</div>'
          }
          ${s.lastError ? `<p class="cc-count" role="alert">${esc(s.lastError)}</p>` : ""}
          <p class="cc-meta" id="evp-status" role="status">${esc(s.status)}</p>
        </div>

        <h3 class="cc-section-title">Recorder References (This Case)</h3>
        ${!caseRecord
          ? '<div class="cc-empty">Select a case to view and create EVP clips.</div>'
          : recorderRefs.length === 0
            ? '<div class="cc-empty">No EVP recordings saved for selected case.</div>'
            : recorderRefs
                .map(
                  (e) => `
              <div class="case-row">
                <div>
                  <div class="case-title">${esc(e.title)}</div>
                  <div class="case-meta">${new Date(e.createdAt).toLocaleString()} • ${esc(e.mediaType)} • integrity: ${esc(e.verificationStatus ?? "unverified")}</div>
                </div>
                <button class="back-button" data-open-analysis="${e.id}" type="button">Open in Audio Analysis</button>
              </div>`,
                )
                .join("")}

        <div class="form-actions"><button class="back-button" id="evp-back" type="button">← Back</button></div>
      </div>
    `,
  ));

  wireHandlers(container);
  wireBackButton(container);
}

function updateMeterUi(container: HTMLElement, meter: RecorderMeterState, elapsedMs: number): void {
  const peak = container.querySelector<HTMLElement>("#evp-peak");
  if (peak) peak.textContent = `Peak: ${meter.currentPeakDBFS.toFixed(1)} dBFS`;
  const max = container.querySelector<HTMLElement>("#evp-max");
  if (max) max.textContent = `Max: ${meter.maxPeakDBFS.toFixed(1)} dBFS`;
  const clips = container.querySelector<HTMLElement>("#evp-clips");
  if (clips) clips.textContent = `Clip Events: ${meter.clipEventCount}`;
  const state = container.querySelector<HTMLElement>("#evp-level-state");
  if (state) {
    state.textContent = meter.levelState;
    state.className = `status-badge ${LEVEL_CLASS[meter.levelState] ?? ""}`;
  }
  const fill = container.querySelector<HTMLElement>("#evp-meter-fill");
  if (fill) {
    // Meter scale: -60…0 dBFS (matches the value the original slider showed).
    const pct = Math.max(0, Math.min(100, ((meter.currentPeakDBFS + 60) / 60) * 100));
    fill.style.width = `${pct}%`;
  }
  const timer = container.querySelector<HTMLElement>("#evp-timer");
  if (timer) timer.textContent = fmtDuration(elapsedMs);
  const warning = container.querySelector<HTMLElement>("#evp-warning");
  if (warning) {
    warning.textContent = meter.sustainedClipWarning
      ? "Warning: sustained clipping detected. Reduce Gain or move farther from source."
      : meter.levelState === "HOT"
        ? `Peak warning threshold: Auto (${meter.hotThresholdDBFS.toFixed(1)} dBFS)`
        : "";
  }
}

function wireHandlers(container: HTMLElement): void {
  const s = st(container);
  const reload = () => renderEvpRecorder(container, s.caseId ?? undefined);

  onDelegate(container, "click", "#evp-back", () => {
    navigate("equipment");
  });
  onDelegate(container, "change", "#evp-case", (el) => {
    s.caseId = (el as HTMLSelectElement).value || null;
    s.sessionId = "";
    s.roomId = "";
    void reload();
  });
  onDelegate(container, "change", "#evp-room", (el) => {
    s.roomId = (el as HTMLSelectElement).value;
  });
  onDelegate(container, "change", "#evp-session", (el) => {
    s.sessionId = (el as HTMLSelectElement).value;
  });
  onDelegate(container, "change", "#evp-rate", (el) => {
    s.sampleRate = Number((el as HTMLSelectElement).value) as SampleRate;
  });
  onDelegate(container, "change", "#evp-auto", (el) => {
    s.autoLevel = (el as HTMLInputElement).checked;
  });

  onDelegate(container, "click", "#evp-record", async () => {
    if (!s.caseId) {
      s.lastError = "Select a case before recording — recordings are saved to case audio readings.";
      await reload();
      return;
    }
    s.lastError = "";
    s.tags = [];
    s.status = "Requesting microphone…";
    const recorder = new EvpRecorder({
      sampleRate: s.sampleRate,
      autoLevelEnabled: s.autoLevel,
      onMeter: (meter) => updateMeterUi(container, meter, recorder.elapsedMs()),
    });
    activeRecorder = recorder;
    const error = await recorder.start();
    if (error) {
      s.lastError = error.message;
      s.status = "Not recording.";
      activeRecorder = null;
      await reload();
      return;
    }
    s.status = "Recording…";
    const rec = container.querySelector<HTMLButtonElement>("#evp-record");
    if (rec) {
      rec.hidden = true;
      rec.textContent = "Recording…";
    }
    for (const id of ["#evp-pause", "#evp-stop", "#evp-cancel", "#evp-tag"]) {
      const el = container.querySelector<HTMLElement>(id);
      if (el) {
        el.hidden = false;
        (el as HTMLButtonElement).disabled = false;
      }
    }
    // Live timer + meter even when Web Audio metering is unavailable.
    const interval = window.setInterval(() => {
      const active = activeRecorder;
      if (!active) return;
      updateMeterUi(container, active.getMeter(), active.elapsedMs());
    }, 250);
    container.dataset.recordingInterval = String(interval);
  });

  onDelegate(container, "click", "#evp-pause", () => {
    const recorder = activeRecorder;
    if (!recorder) return;
    const btn = container.querySelector<HTMLButtonElement>("#evp-pause");
    if (recorder.getState() === "paused") {
      recorder.resume();
      if (btn) btn.textContent = "Pause";
    } else {
      recorder.pause();
      if (btn) btn.textContent = "Resume";
    }
  });

  onDelegate(container, "click", "#evp-tag", () => {
    const recorder = activeRecorder;
    const note = window.prompt("Anomaly tag note (what did you notice?)", "");
    if (note === null) return;
    recorder?.tagAnomaly(note.trim() || "Anomaly tagged");
  });

  onDelegate(container, "click", "#evp-stop", async () => {
    const recorder = activeRecorder;
    if (!recorder) return;
    clearInterval(Number(container.dataset.recordingInterval ?? "0"));
    s.status = "Saving to case audio readings…";
    const result = await recorder.stop();
    activeRecorder = null;
    if (!result || result.blob.size === 0) {
      s.lastError = "The recording produced no audio data, so nothing was saved.";
      s.status = "Not saved.";
      await reload();
      return;
    }
    // Persist through the existing evidence pipeline (OPFS + SHA-256 + audit).
    const repo = new EvidenceRepository(db());
    const file = new File([result.blob], result.originalFileName, { type: result.mimeType });
    const evidence = await repo.storeOriginal({
      caseId: s.caseId!,
      sessionId: s.sessionId || undefined,
      mediaType: "audio",
      title: `EVP ${new Date(result.recordedAt).toLocaleString()}`,
      fileName: result.originalFileName,
      data: file,
      origin: "evp-recorder",
      recordedBy: "local-user",
    });
    await db().evidence.put({
      ...evidence,
      originalFileName: result.originalFileName,
      sourceDescription: `Recorded in-app (EVP). Route: ${result.routeLabel}. ${result.sampleRate} Hz target.`,
      importedAt: Date.now(),
      verificationStatus: "verified",
      verifiedAt: Date.now(),
      verificationDetail: "Stored unchanged from the recorder and hashed on write.",
      roomId: s.roomId || null,
      captureTimestamp: result.recordedAt,
      captureTimestampSource: "capture",
      captureTimezoneOffsetMinutes: -new Date().getTimezoneOffset(),
      notes: [
        `Duration: ${fmtDuration(result.durationMs)}`,
        `Container: ${result.mimeType}`,
        `Max peak: ${result.meter.maxPeakDBFS.toFixed(1)} dBFS`,
        `Clip events: ${result.meter.clipEventCount}`,
        result.tags.length > 0 ? `Anomaly tags: ${result.tags.map((t) => `${fmtDuration(t.atMs)} ${t.note}`).join("; ")}` : "",
        s.sessionId ? `Session: ${s.sessionId}` : "No session association",
      ]
        .filter(Boolean)
        .join(" • "),
    });
    await new AuditService(db()).record("evidenceImported", "EVP recording saved to case audio readings.", {
      caseId: s.caseId!,
      affectedRecordId: evidence.id,
      metadata: { mediaType: "audio", durationMs: result.durationMs, clipEvents: result.meter.clipEventCount, tags: result.tags.length },
    });
    s.lastResult = result;
    s.tags = result.tags;
    s.status = "Saved to case audio readings.";
    await reload();
  });

  onDelegate(container, "click", "#evp-cancel", async () => {
    if (!window.confirm("Cancel this recording? Nothing will be saved.")) return;
    clearInterval(Number(container.dataset.recordingInterval ?? "0"));
    await activeRecorder?.cancel();
    activeRecorder = null;
    s.lastResult = null;
    s.status = "Recording cancelled — nothing was saved.";
    await reload();
  });

  onDelegate(container, "click", "[data-open-analysis]", (el) => {
    const id = el.dataset.openAnalysis ?? "";
    navigate("forensic");
    void import("../forensic/AudioAnalysis").then((m) => m.renderAudioAnalysis(document.querySelector<HTMLElement>("#app")!, id));
  });
}

/** Release the microphone if the investigator navigates away mid-recording. */
export async function releaseEvpRecorder(): Promise<void> {
  await activeRecorder?.dispose();
  activeRecorder = null;
}

export type { MeterSnapshot };
